var _markdown = "\n\n`CWaterLevel.h`\n\n水面高度、波浪、渲染入口。贴水、游泳、船相关判断常用。\n\n## 取水面高度 [#取水面高度]\n\n<Api name=\"GetWaterLevel / GetWaterLevelNoWaves\">\n  成功写 `*pWaterZ`。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static bool GetWaterLevel(/* 重载见头文件：坐标 + out Z + 波浪相关 */);\n      static bool GetWaterLevelNoWaves(float x, float y, float z, float* pWaterZ);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      float wz = 0.0f;\n      CVector p = ped->GetPosition();\n      if (CWaterLevel::GetWaterLevelNoWaves(p.x, p.y, p.z, &wz)) {\n          // wz 为无浪水面\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 波浪叠加 [#波浪叠加]\n\n<Api name=\"AddWaveToResult / CalculateWavesOnlyForCoordinate\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void AddWaveToResult(float x, float y, float* pWaterZ, float BigWavesAmpl, float SmallWavesAmpl, CVector* pNormal);\n      static void CalculateWavesOnlyForCoordinate(int32_t X, int32_t Y, float BigWavesAmpl, float SmallWavesAmpl, float* pResultHeight);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 在已有 waterZ 上叠浪\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 配置与顶点 [#配置与顶点]\n\n<Api name=\"m_nWaterConfiguration / ChangeWaterConfiguration\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static int& m_nWaterConfiguration;\n      static void ChangeWaterConfiguration(int32_t NewWaterConfig);\n      static int& m_nNumOfWaterTriangles;\n      static int& m_nNumOfWaterQuads;\n      static int& m_nNumOfWaterVertices;\n      static std::array<CWaterVertex, 1021>& m_aVertices;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 改配置影响整图水面；调试用，别常驻乱切\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 沙滩玩具 [#沙滩玩具]\n\n<Api name=\"CreateBeachToy\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static CObject* CreateBeachToy(const CVector* pos, eBeachToy beachToy);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // CObject* o = CWaterLevel::CreateBeachToy(&pos, toy);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 渲染入口 [#渲染入口]\n\n<Api name=\"RenderWater / PreRenderWater\">\n  一般只 hook 观察，别每帧瞎调。\n\n  ```cpp\n  static void PreRenderWater();\n  static void RenderWater();\n  static void RenderTransparentWater();\n  static void RenderWaterFog();\n  ```\n</Api>\n";
